.choice {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
  position: relative;
  user-select: none;
}

.choice:hover {
  border-color: var(--color-primary);
  background: var(--color-primary-light);
}

.choice input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

/* Custom checkbox box */
.choice-box {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  border: 2px solid var(--color-border);
  border-radius: 5px;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color var(--transition), background var(--transition);
}

.choice-box svg {
  opacity: 0;
  transform: scale(.6);
  transition: opacity var(--transition), transform var(--transition);
}

.choice input[type="checkbox"]:checked ~ .choice-box {
  background: var(--color-primary);
  border-color: var(--color-primary);
}

.choice input[type="checkbox"]:checked ~ .choice-box svg {
  opacity: 1;
  transform: scale(1);
}

.choice:has(input[type="checkbox"]:checked) {
  border-color: var(--color-primary);
  background: var(--color-primary-light);
  box-shadow: 0 0 0 3px rgba(79,70,229,.12);
}

.choice-text {
  font-size: .95rem;
  font-weight: 500;
  color: var(--color-text);
  flex: 1;
}

/* Focus ring for keyboard nav */
.choice input[type="checkbox"]:focus-visible ~ .choice-box {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

/* ── Submit button ───────────────────────────────────── */
.submit-wrap {
  text-align: center;
  margin-top: 8px;
