  {
    id: "q1",
    number: "01",
    text: "Which of the following are compiled languages?",
    helpText:
      "A compiled language is translated into machine code before execution, rather than being interpreted line-by-line at runtime. This often results in faster execution speeds.",
    choices: [
      { value: "c", label: "C" },
      { value: "python", label: "Python" },
      { value: "rust", label: "Rust" },
      { value: "javascript", label: "JavaScript" },
    ],
    correct: ["c", "rust"],
  },
  {
    id: "q2",
    number: "02",
    text: "Which of the following languages were created at Bell Labs?",
    choices: [
      { value: "c", label: "C" },
      { value: "java", label: "Java" },
      { value: "awk", label: "AWK" },
      { value: "python", label: "Python" },
    ],
    correct: ["c", "awk"],
  },
  {
    id: "q3",
    number: "03",
    text: "Which of the following languages were created by Google?",
    choices: [
      { value: "go", label: "Go" },
      { value: "kotlin", label: "Kotlin" },
      { value: "dart", label: "Dart" },
      { value: "typescript", label: "TypeScript" },
    ],
    correct: ["go", "dart"],
  },
];

// ── Component builders ────────────────────────────────────────────────────────

function createCheckIcon() {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("width", "12");
  svg.setAttribute("height", "12");
  svg.setAttribute("viewBox", "0 0 12 12");
  svg.setAttribute("fill", "none");
  svg.setAttribute("aria-hidden", "true");
  const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
  path.setAttribute("d", "M2 6l3 3 5-5");
  path.setAttribute("stroke", "#fff");
  path.setAttribute("stroke-width", "2");
  path.setAttribute("stroke-linecap", "round");
  path.setAttribute("stroke-linejoin", "round");
  svg.appendChild(path);
  return svg;
}

function createInfoIcon() {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("width", "16");
  svg.setAttribute("height", "16");
  svg.setAttribute("viewBox", "0 0 16 16");
  svg.setAttribute("fill", "none");
  svg.setAttribute("aria-hidden", "true");
  svg.innerHTML = `
    <circle cx="8" cy="8" r="7" stroke="#6366f1" stroke-width="1.5"/>
    <path d="M8 7v4" stroke="#6366f1" stroke-width="1.5" stroke-linecap="round"/>
    <circle cx="8" cy="5" r=".75" fill="#6366f1"/>
  `;
  return svg;
}

function createChoiceItem(choice, questionId) {
  const li = document.createElement("li");

  const label = document.createElement("label");
  label.className = "choice";
  label.htmlFor = `${questionId}-${choice.value}`;

  const input = document.createElement("input");
  input.type = "checkbox";
  input.id = `${questionId}-${choice.value}`;
  input.name = questionId;
  input.value = choice.value;
  // Sync checked state → visual on change
  input.addEventListener("change", () => {});

  const box = document.createElement("span");
  box.className = "choice-box";
  box.setAttribute("aria-hidden", "true");
  box.appendChild(createCheckIcon());

  const text = document.createElement("span");
  text.className = "choice-text";
  text.textContent = choice.label;

  label.appendChild(input);
  label.appendChild(box);
  label.appendChild(text);
  li.appendChild(label);
  return li;
}

function createFormField(question) {
  const field = document.createElement("div");
  field.className = "form-field";
  field.setAttribute("role", "group");
  field.setAttribute("aria-labelledby", `legend-${question.id}`);

  // Question number badge + label
  const meta = document.createElement("div");
  meta.className = "question-meta";
  const num = document.createElement("span");
  num.className = "question-number";
  num.textContent = `Question ${question.number}`;
  meta.appendChild(num);

  const labelEl = document.createElement("p");
  labelEl.className = "question-label";
  labelEl.id = `legend-${question.id}`;
  labelEl.textContent = question.text;

  field.appendChild(meta);
  field.appendChild(labelEl);

  // Optional help text (only first question)
  if (question.helpText) {
    const help = document.createElement("div");
    help.className = "help-text";
    help.setAttribute("role", "note");
    help.appendChild(createInfoIcon());
    const helpP = document.createElement("span");
    helpP.textContent = question.helpText;
    help.appendChild(helpP);
    field.appendChild(help);
  }

  // Choices
  const ul = document.createElement("ul");
  ul.className = "choices";
  question.choices.forEach((choice) => {
    ul.appendChild(createChoiceItem(choice, question.id));
  });
  field.appendChild(ul);

  return field;
}

// ── Quiz state & scoring ──────────────────────────────────────────────────────

function getAnswers(questionId) {
  return Array.from(
    document.querySelectorAll(`input[name="${questionId}"]:checked`)
  ).map((cb) => cb.value);
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false;
  const sa = [...a].sort();
  const sb = [...b].sort();
  return sa.every((v, i) => v === sb[i]);
}

function scoreQuiz() {
  return QUESTIONS.map((q) => {
    const selected = getAnswers(q.id);
    const isCorrect = arraysEqual(selected, q.correct);
    return { question: q, selected, isCorrect };
  });
}

function showResults(results) {
  const panel = document.getElementById("results");
  panel.innerHTML = "";

  const correctCount = results.filter((r) => r.isCorrect).length;
  const total = results.length;

  // Header
  const header = document.createElement("div");
  header.className = "results-header";

  const scoreBadge = document.createElement("div");
  scoreBadge.className = "score-badge";
  scoreBadge.setAttribute("aria-label", `Score: ${correctCount} out of ${total}`);
  scoreBadge.textContent = `${correctCount}/${total}`;

  const titleWrap = document.createElement("div");
  const title = document.createElement("div");
  title.className = "results-title";
  title.textContent =
    correctCount === total
      ? "🎉 Perfect Score!"
      : correctCount >= total / 2
      ? "Good effort!"
      : "Keep studying!";
  const subtitle = document.createElement("div");
  subtitle.className = "results-subtitle";
  subtitle.textContent = `You answered ${correctCount} of ${total} questions correctly.`;
  titleWrap.appendChild(title);
  titleWrap.appendChild(subtitle);
  header.appendChild(scoreBadge);
  header.appendChild(titleWrap);
  panel.appendChild(header);

  // Per-question result
  results.forEach(({ question, selected, isCorrect }) => {
    const item = document.createElement("div");
    item.className = `result-item ${isCorrect ? "correct" : "incorrect"}`;
    item.setAttribute("role", "status");

    const icon = document.createElement("span");
    icon.className = "icon";
    icon.setAttribute("aria-hidden", "true");
    icon.textContent = isCorrect ? "✓" : "✗";

    const detail = document.createElement("div");
    detail.className = "result-detail";

    const strong = document.createElement("strong");
    strong.textContent = question.text;
    detail.appendChild(strong);

    const correctLabels = question.correct
      .map((v) => question.choices.find((c) => c.value === v)?.label)
      .join(", ");

    const info = document.createElement("span");
    if (isCorrect) {
      info.textContent = `Correct! Answer: ${correctLabels}`;
    } else {
      const selectedLabels =
        selected.length > 0
          ? selected
              .map((v) => question.choices.find((c) => c.value === v)?.label)
              .join(", ")
          : "None selected";
      info.textContent = `Your answer: ${selectedLabels} — Correct answer: ${correctLabels}`;
    }
    detail.appendChild(info);

    item.appendChild(icon);
    item.appendChild(detail);
    panel.appendChild(item);
  });

  // Retry button
  const retryBtn = document.createElement("button");
  retryBtn.type = "button";
  retryBtn.className = "btn-retry";
  retryBtn.setAttribute("aria-label", "Retry the quiz");
  retryBtn.innerHTML = `↺ Try Again`;
  retryBtn.addEventListener("click", resetQuiz);
  panel.appendChild(retryBtn);

  panel.classList.add("visible");
  panel.scrollIntoView({ behavior: "smooth", block: "start" });
}

function resetQuiz() {
  document.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
    cb.checked = false;
  });
  const panel = document.getElementById("results");
  panel.classList.remove("visible");
  panel.innerHTML = "";
  document.querySelector(".quiz-form").scrollIntoView({ behavior: "smooth" });
}

// ── Bootstrap ─────────────────────────────────────────────────────────────────

function buildQuiz() {
  const form = document.getElementById("quiz-form");

  QUESTIONS.forEach((q) => {
    form.insertBefore(createFormField(q), form.querySelector(".submit-wrap"));
  });

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    showResults(scoreQuiz());
  });
}

document.addEventListener("DOMContentLoaded", buildQuiz);
